package fleetflow.engine.flow;
import java.util.*;
public final class MinCut { private MinCut(){} /** Returns vertices reachable from source in the residual graph after maximum flow. */ public static boolean[] sourceSide(int[][] capacity,int source,int sink){int n=capacity.length;int[][] r=new int[n][n];for(int i=0;i<n;i++)r[i]=capacity[i].clone();int[] p=new int[n];while(true){Arrays.fill(p,-1);p[source]=source;Queue<Integer>q=new ArrayDeque<>();q.add(source);while(!q.isEmpty()&&p[sink]<0){int u=q.remove();for(int v=0;v<n;v++)if(p[v]<0&&r[u][v]>0){p[v]=u;q.add(v);}}if(p[sink]<0)break;int f=Integer.MAX_VALUE;for(int v=sink;v!=source;v=p[v])f=Math.min(f,r[p[v]][v]);for(int v=sink;v!=source;v=p[v]){int u=p[v];r[u][v]-=f;r[v][u]+=f;}}boolean[] seen=new boolean[n];Queue<Integer>q=new ArrayDeque<>();q.add(source);seen[source]=true;while(!q.isEmpty()){int u=q.remove();for(int v=0;v<n;v++)if(!seen[v]&&r[u][v]>0){seen[v]=true;q.add(v);}}return seen;} }
